const now = new Date();

return [{
  json: {
    execution_id: `run_${now.getTime()}`,
    timestamp: now.toISOString(),
    date: now.toISOString().split('T')[0],
    sources_to_fetch: ['api_1', 'files', 'database', 'JARVIS_BRAIN'],
    status: 'started'
  }
}];

const fs = require('fs');
const path = '/home/seu-usuario/dados/arquivo.json';

const raw = fs.readFileSync(path, 'utf-8');
const data = JSON.parse(raw);
const lines = raw.split('\n');
const headers = lines[0].split(',');
const data = lines.slice(1).filter(l => l).map(line => {
  const vals = line.split(',');
  return Object.fromEntries(headers.map((h, i) => [h.trim(), vals[i]?.trim()]));
});
return data.map(item => ({ json: item }));

// Normalizer genérico — adapte os campos para cada fonte
const items = $input.all();

return items.map(item => {
  const d = item.json;
  return {
    json: {
      source: 'api',          // troque por 'file' ou 'database' conforme o branch
      id: d.id ?? d._id ?? null,
      title: d.title ?? d.nome ?? d.name ?? '',
      content: d.content ?? d.descricao ?? d.text ?? '',
      date: d.date ?? d.created_at ?? new Date().toISOString(),
      raw: d                  // mantém o original para debug
    }
  };
});

