const items = $input.all();

// Monta o contexto a partir dos dados coletados
const contexto = items.map((item, i) => {
  const d = item.json;
  return `[${i+1}] Fonte: ${d.source} | ${d.date}\nTítulo: ${d.title}\nConteúdo: ${d.content}`;
}).join('\n\n');

const prompt = `Você é um assistente de análise. Analise os dados abaixo e gere um resumo estruturado com:
1. Principais insights
2. Padrões identificados
3. Pontos de atenção
4. Recomendações

DADOS:
${contexto}

Responda em JSON com as chaves: insights, padroes, atencao, recomendacoes.`;

return [{
  json: {
    prompt,
    model: 'seu-modelo-aqui',   // nome exato como aparece no LM Studio
    item_count: items.length,
    timestamp: new Date().toISOString()
  }
}];

const response = $input.first().json;

// Extrai o texto da resposta
const rawText = response.choices[0].message.content;

// Tenta parsear como JSON
let parsed;
try {
  // Remove possíveis backticks que o modelo às vezes inclui
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Se não for JSON válido, salva como texto livre
  parsed = { raw_text: rawText, parse_error: true };
}

return [{
  json: {
    ...parsed,
    model_used: response.model,
    tokens_used: response.usage?.total_tokens ?? 0,
    generated_at: new Date().toISOString()
  }
}];

const d = $input.first().json;
const now = new Date();
const date = now.toISOString().split('T')[0];

// Payload 1: nota Markdown para o Obsidian
const notaMD = `---
date: ${date}
tags: [agente-ia, análise-automática]
tokens: ${d.tokens_used ?? 0}
---

# Análise ${date}

## Insights
${(d.insights ?? []).map(i => `- ${i}`).join('\n')}

## Padrões identificados
${(d.padroes ?? []).map(p => `- ${p}`).join('\n')}

## Pontos de atenção
${(d.atencao ?? []).map(a => `- ${a}`).join('\n')}

## Recomendações
${(d.recomendacoes ?? []).map(r => `- ${r}`).join('\n')}
`;

// Payload 2: objeto HTTP para o dashboard
const payloadDashboard = {
  date,
  insights:       d.insights       ?? [],
  padroes:        d.padroes        ?? [],
  atencao:        d.atencao        ?? [],
  recomendacoes:  d.recomendacoes  ?? [],
  tokens_used:    d.tokens_used    ?? 0,
  generated_at:   now.toISOString()
};

// Payload 3: memória para o Discord (Workflow 2)
const memoriaJSON = {
  date,
  resumo: (d.insights ?? []).slice(0, 3),
  atencao: d.atencao ?? [],
  recomendacoes: d.recomendacoes ?? [],
  tokens_used: d.tokens_used ?? 0,
  run_at: now.toISOString()
};

return [{
  json: {
    nota_md:            notaMD,
    vault_path:         `/home/seu-usuario/Obsidian/Vault/Analises/analise-${date}.md`,
    payload_dashboard:  payloadDashboard,
    memoria_json:       memoriaJSON,
    memoria_path:       '/home/seu-usuario/jarvis/jarvis_memoria.json'
  }
}];

const fs   = require('fs');
const path = require('path');
const d    = $input.first().json;

const dir = path.dirname(d.vault_path);
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

fs.writeFileSync(d.vault_path, d.nota_md, 'utf-8');

return [{ json: { obsidian_status: 'saved', file: d.vault_path } }];

const fs   = require('fs');
const path = require('path');
const d    = $input.first().json;

const dir = path.dirname(d.memoria_path);
if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

// Mantém histórico dos últimos 7 dias
let historico = [];
if (fs.existsSync(d.memoria_path)) {
  try {
    historico = JSON.parse(fs.readFileSync(d.memoria_path, 'utf-8'));
  } catch(e) { historico = []; }
}

historico.unshift(d.memoria_json);           // adiciona o dia de hoje no topo
if (historico.length > 7) historico.pop();   // mantém só os últimos 7

fs.writeFileSync(d.memoria_path, JSON.stringify(historico, null, 2), 'utf-8');

return [{ json: { memoria_status: 'saved', entries: historico.length } }];

// Code JS simples para logar o erro
const erro = $input.first().json;

return [{
  json: {
    workflow: erro.workflow?.name ?? 'desconhecido',
    node:     erro.execution?.lastNodeExecuted ?? '',
    msg:      erro.execution?.error?.message ?? 'sem detalhe',
    at:       new Date().toISOString()
  }
}];
